                    run_id="same-actual-worker-run",
                    budget_state=state,
                )
            return await translator.PolicyTranslatorWorker(
                translator.PolicyTranslatorConfig(model_name="explicit-worker-oracle-model")
            ).translate_async(bundle)

        outcomes = []
        sys.settrace(observe)
        try:
            for _ in range(2):
